'use strict';
const E=FinoraEngine,T=TEMPLATE,$=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const nf=new Intl.NumberFormat('en-US',{maximumFractionDigits:2}),names={Sektör:'Sektör',Ozel:'Özel bankalar',Kamu:'Kamu bankaları'};
const bsTitles={3:'Toplam krediler',4:'TL krediler',6:'YP krediler',12:'Bireysel krediler',21:'Ticari krediler',28:'KOBİ kredileri',31:'Kredi kartları',37:'Toplam mevduat',38:'TL mevduat',39:'FX mevduat',42:'TL vadeli',50:'TL vadesiz',43:'FX vadeli',51:'FX vadesiz',41:'Vadeli mevduat',49:'Vadesiz mevduat',57:'Kredi / mevduat'};
const plTitles={49:'Net faiz geliri',53:'Net ücret & komisyon',57:'Faaliyet giderleri',60:'Karşılık öncesi kâr',61:'Beklenen kredi zararı',65:'Net kâr',67:'Aktif kârlılığı',68:'Özkaynak kârlılığı',69:'Gider / gelir',70:'Net faiz marjı',11:'Net faiz geliri',15:'Net ücret & komisyon',19:'Faaliyet giderleri',22:'Karşılık öncesi kâr',23:'Beklenen kredi zararı',27:'Net kâr',29:'Aktif kârlılığı',30:'Özkaynak kârlılığı',31:'Gider / gelir',32:'Net faiz marjı'};
const ratio=(type,row)=>T[type].rows.find(r=>r.row===row)?.ratio??(type==='BS'?row===57:[29,30,31,32,45,67,68,69,70,83].includes(row));
const cumulative=Object.fromEntries(T.PL.rows.filter(r=>r.row>=49).map(r=>[r.row,r.cumulativeRow??r.row-38]));
const children={3:[4,6,104],12:[112,15,17,18,114,19,116],21:[23,25,28,29],31:[32,33,34,35],37:[38,39],41:[42,43,44,45,46,47],49:[50,51,52,53,54,55]};
let state={view:'overview',group:'Sektör',date:'',unit:1000,basis:'monthly',horizon:'change',trend:3};
let dataset={sheets:[],warnings:[],demo:false},loadState='loading',loadError='',loadToken=0,lastRead=null;
const sheet=(type,group=state.group)=>dataset.sheets.find(s=>s.type===type&&s.group===group);
function getSeries(type,row,group=state.group){return E.metricSeries(sheet(type,group),row).map(p=>({...p,value:E.finite(p.value)?p.value:null}));}
function metric(type,row,group=state.group){return E.monthlyCompare(getSeries(type,row,group),latestDate(type,group)||state.date,type,ratio(type,row),type==='PL'&&row>=11&&row<=45,new Date().toISOString().slice(0,10));}
const displayLabel=(type,text)=>type==='PL'?String(text??'').replace(/^(monthly|cumulative)\s+/i,''):text;
function label(type,row){return displayLabel(type,(type==='BS'?bsTitles[row]:null)||T[type].rows.find(r=>r.row===row)?.label||'Kalem');}
function amount(v,isRatio=false){return !E.finite(v)?'—':(isRatio?'%':'')+(state.unit===1000000&&!isRatio?new Intl.NumberFormat('en-US',{maximumFractionDigits:2}):nf).format(isRatio?v:v/state.unit);}
const currency=(type,row)=>T[type]?.rows.find(r=>r.row===row)?.format==='USD'?'USD':'TL';
const unit=(type,row)=>(state.unit===1000000?'trln ':state.unit===1000?'mlr ':'mn ')+currency(type,row);
function change(v,isRatio=false){return !E.finite(v)?'<span class="muted">—</span>':`<span class="change">${v>0?'+':''}${nf.format(v)}${isRatio?' puan':'%'}</span>`;}
const dateLabel=d=>d?new Date(d+'T00:00:00Z').toLocaleDateString('tr-TR',{day:'numeric',month:'short',year:'numeric',timeZone:'UTC'}):'Veri yok';
const monthLabel=d=>d?new Date(d+'T00:00:00Z').toLocaleDateString('tr-TR',{month:'long',year:'numeric',timeZone:'UTC'}):'Veri yok';
const horizonLabel=(type,h=state.horizon)=>h==='change'?'MoM':h==='yoyChange'?'YoY':type==='PL'?'YTD YoY':'YTD';
let detailLevelKey='';
function detailMode(type,row){return ratio(type,row)&&detailLevelKey===type+':'+row?'nominal':state.horizon;}
function chartPoints(type,row,mode=state.horizon){const latest=latestDate(type)||state.date;const d=new Date(latest+'T00:00:00Z'),end=E.monthEnd(d.getUTCFullYear(),d.getUTCMonth()),cut=type==='BS'&&new Date().toISOString().slice(0,10)>=end?end:latest;return E.monthlyChanges(getSeries(type,row),cut,type,mode,ratio(type,row),type==='PL'&&row>=11&&row<=45,getSeries(type,cumulative[row]||row));}
function spark(points){const valid=points.filter(p=>E.finite(p.value));if(valid.length<2)return '';const lo=Math.min(...valid.map(p=>p.value)),hi=Math.max(...valid.map(p=>p.value));let path='',open=false;points.forEach((p,i)=>{if(!E.finite(p.value)){open=false;return;}path+=`${open?'L':'M'}${i*84/11},${29-(p.value-lo)/(hi-lo||1)*26} `;open=true;});return `<svg class="spark" viewBox="0 0 85 32" aria-hidden="true"><path d="${path}" fill="none" stroke="#5d88f2" stroke-width="1.8"/></svg>`;}
function chartControls(type,row){const mode=detailMode(type,row),choices=[['change','MoM'],['yoyChange','YoY'],['ytdChange',type==='PL'?'YTD YoY':'YTD'],...(ratio(type,row)?[['nominal','Oran']]:[])];return `<div class="section-head"><h3>Son 12 ay · ${mode==='nominal'?'Oran seviyesi':horizonLabel(type)+' değişimi'}</h3><div class="mini-controls">${choices.map(([h,t])=>`<button data-detail-horizon="${h}" data-detail-key="${type}:${row}" class="${mode===h?'selected':''}">${t}</button>`).join('')}</div></div>`;}
function card(type,row){const m=metric(type,row),r=ratio(type,row),h=state.horizon,ytdMetric=type==="PL"?metric(type,cumulative[row]||row):null,val=h==='yoyChange'?m.yoyChange:h==='ytdChange'?(type==='PL'?ytdMetric.yoyChange:m.ytdChange):m.change,shown=h==='ytdChange'&&type==='PL'?ytdMetric:m;
return `<button class="card" data-metric="${type}:${row}" aria-label="${esc(label(type,row))} detayını aç"><div class="card-top"><span>${esc(label(type,row))}</span><span>${r?'ORAN':type==='BS'?'STOK':(row<49||h==='ytdChange')?'KÜMÜLATİF':'AYLIK'}</span></div><div class="value">${amount(shown.current?.value,r)}${r?'':`<small>${unit(type,row)}</small>`}</div><div class="source-text">${type==='BS'?dateLabel(shown.current?.date):monthLabel(shown.current?.date)}${type==='BS'&&m.provisional?' · Geçici dönem':''}</div><div class="card-bottom"><span>${change(val,r)} <span class="muted">${h==='yoyChange'?'YoY':h==='ytdChange'?(type==='PL'?'YTD YoY':'YTD'):(type==='BS'?'MoM':row<49?'MoM · YTD':'MoM')}</span></span>${spark(chartPoints(type,row))}</div></button>`;}
function latestDate(type,group=state.group){const source=sheet(type,group);return source?.dates.filter((d,i)=>source.rows.some(r=>E.finite(r.values[i]))).sort().at(-1);}
function dateFor(type){return latestDate(type);}
function section(title,type,rows){return `<div class="section-head"><h3>${title}</h3><span class="muted">${type==='BS'?'Haftalık · '+dateLabel(dateFor(type)):(rows[0]<49?'Kümülatif · ':'Aylık · ')+monthLabel(dateFor(type))}</span></div><div class="cards">${rows.map(r=>card(type,r)).join('')}</div>`;}
function titleStyle(type,row,subtitle=false){const s=T[type].rows.find(r=>r.row===row)?.titleStyle||{};return `style="padding-inline-start:${Math.min(8,Math.max(0,s.indent||0))*18}px;${!subtitle&&s.gray?'color:#808080;':''}${subtitle?'':`font-weight:${s.bold?700:400}`}"`;}
function table(type,rows){if(type==='BS')rows=[...rows].sort((a,b)=>(T.BS.rows.find(r=>r.row===a)?.sourceRow??a)-(T.BS.rows.find(r=>r.row===b)?.sourceRow??b));return `<div class="table-wrap"><table><thead><tr><th>Finansal kalem</th><th>Tutar / oran · kaynak birimi</th><th>${type==='BS'?'MoM':'MoM'}</th><th>YoY</th><th>${type==='BS'?'YTD':'YTD kümülatif'}</th></tr></thead><tbody>${rows.map(row=>{
const m=metric(type,row),r=ratio(type,row),cu=type==='PL'&&cumulative[row]?E.cumulativeYoY(sheet(type),cumulative[row],latestDate(type)||state.date):type==='PL'&&row>=11&&row<=45?{current:m.current}:null;
return `<tr data-metric="${type}:${row}" tabindex="0" role="button" aria-label="${esc(label(type,row))} detayını aç"><td><div class="table-title" ${titleStyle(type,row)}>${esc(label(type,row))}</div></td><td>${amount(m.current?.value,r)}${r?'':' '+unit(type,row)}</td><td>${change(m.change,r)}</td><td>${change(m.yoyChange,r)}</td><td>${type==='BS'?change(m.ytdChange,r):cu?amount(cu.current?.value,r)+(r?'':' '+unit(type,row)):'—'}</td></tr>`;}).join('')}</tbody></table></div>`;}
function chart(points,{isRatio=false,title='MoM',level=false}={}){
 const valid=points.filter(p=>E.finite(p.value));if(!valid.length)return '<div class="empty">Son 12 ay için karşılaştırılabilir veri yok.</div>';
 let lo=Math.min(0,...valid.map(p=>p.value)),hi=Math.max(0,...valid.map(p=>p.value)),pad=(hi-lo)*.22||1;lo-=pad;hi+=pad;
 const x=i=>64+i*836/11,y=v=>238-(v-lo)/(hi-lo)*184,fmt=v=>nf.format(v)+(isRatio&&!level?' p':'%');let path='',open=false;
 let svg=`<div class="chart-scroll"><svg class="chart" viewBox="0 0 960 300" role="img" aria-label="Son 12 ay ${esc(title)} değişimi; ${isRatio&&!level?'yüzde puan':'yüzde'}">`;
 for(let i=0;i<4;i++){const v=lo+(hi-lo)*i/3,yp=y(v);svg+=`<line x1="64" y1="${yp}" x2="912" y2="${yp}" stroke="#e8eef7" stroke-dasharray="3 4"/><text x="52" y="${yp+4}" text-anchor="end">${nf.format(v)}</text>`;}
 points.forEach((p,i)=>{if(!E.finite(p.value)){open=false;return;}path+=`${open?'L':'M'}${x(i).toFixed(1)},${y(p.value).toFixed(1)} `;open=true;});
 svg+=`<path class="change-line" d="${path}" fill="none" stroke="#245de8" stroke-width="2.8" stroke-linejoin="round"/>`;
 points.forEach((p,i)=>{const v=E.finite(p.value);svg+=v?`<circle cx="${x(i)}" cy="${y(p.value)}" r="4" fill="#245de8"><title>${dateLabel(p.sourceDate)} · ${fmt(p.value)}</title></circle><text class="point-label" x="${x(i)}" y="${y(p.value)-13}" text-anchor="middle">${fmt(p.value)}</text>`:`<text x="${x(i)}" y="238" text-anchor="middle">—</text>`;const d=new Date(p.date+'T00:00:00Z');svg+=`<text x="${x(i)}" y="270" text-anchor="middle">${d.toLocaleDateString('tr-TR',{month:'short',timeZone:'UTC'})}</text><text x="${x(i)}" y="287" text-anchor="middle">${d.getUTCFullYear()}</text>`;});
 return svg+'</svg></div><div class="chart-caption">'+esc(title)+' · '+(level?'Oran (%)':isRatio?'Yüzde puan':'Yüzde değişim')+' · Ay başına tek gözlem. Son ay, seçili tarihe kadar olan veriyi içerir; eksik karşılaştırmalar “—” gösterilir.</div>';
}
function loanPie(currency=null){
 const deposits=!!currency,depositName=currency==='TL'?'TL mevduat':'FX mevduat';
 const pieUnit=unit('BS',currency==='FX'?39:3);
 const total=metric('BS',deposits?(currency==='TL'?38:39):3).current,rows=deposits?(currency==='TL'?[42,50]:[43,51]):[12,21,31],colors=currency==='FX'?['#21a59a','#82c9c1']:['#245de8','#7999ef','#21a59a'];
 const parts=rows.map((row,i)=>({row,color:colors[i],point:total?E.at(getSeries('BS',row),total.date):null}));
 const valid=total&&total.value>0&&parts.every(p=>p.point&&p.point.value>=0),sum=valid?parts.reduce((n,p)=>n+p.point.value,0):0;
 if(!valid||sum<=0)return `<div class="empty">${deposits?depositName:'Kredi'} dağılımı için aynı tarihli tüm kırılım verileri gerekiyor.</div>`;
 const mismatch=Math.abs(sum-total.value)/total.value>.005;
 if(mismatch)return `<div class="empty">${deposits?depositName:'Kredi'} kırılımı toplamı (${amount(sum)} ${pieUnit}) ${deposits?depositName+' toplamıyla':'toplam kredilerle'} (${amount(total.value)} ${pieUnit}) eşleşmiyor. ${dateLabel(total.date)} tarihindeki kaynak kapsamını kontrol edin.</div>`;
 let angle=-Math.PI/2;
 const slices=parts.map(p=>{const share=p.point.value/sum,next=angle+share*2*Math.PI,start=[110+86*Math.cos(angle),110+86*Math.sin(angle)],end=[110+86*Math.cos(next),110+86*Math.sin(next)],path=share>=.999999?`<circle cx="110" cy="110" r="86" fill="${p.color}"/>`:`<path d="M110,110 L${start.join(',')} A86,86 0 ${share>.5?1:0},1 ${end.join(',')} Z" fill="${p.color}" stroke="white" stroke-width="2"/>`;const mid=(angle+next)/2,tx=110+57*Math.cos(mid),ty=110+57*Math.sin(mid);angle=next;return `<g><title>${esc(label('BS',p.row))} · ${amount(p.point.value)} ${pieUnit} · Pay %${nf.format(share*100)}</title>${path}<text class="pie-share" x="${tx.toFixed(1)}" y="${ty.toFixed(1)}" text-anchor="middle" dominant-baseline="middle">%${nf.format(share*100)}</text></g>`;}).join('');
 return `<div class="loan-pie-body"><button class="pie-history-trigger" data-pie-history="${currency||'loans'}" aria-label="${deposits?depositName:'Kredi'} son 12 aylık dağılımını aç"><svg viewBox="0 0 220 220" role="img" aria-label="${deposits?depositName+': vadeli ve vadesiz dağılımı':'Toplam krediler: bireysel, ticari ve kredi kartı dağılımı'}">${slices}</svg><span>12 aylık dağılım →</span></button><div class="loan-pie-legend">${parts.map(p=>`<button data-metric="BS:${p.row}"><span class="pie-dot" style="background:${p.color}"></span><span>${esc(label('BS',p.row))}<small>${amount(p.point.value)} ${pieUnit}</small></span></button>`).join('')}<p class="source-text">${dateLabel(total.date)} · ${names[state.group]} · Toplam ${amount(total.value)} ${pieUnit}</p></div></div>`;
}
let pieComparison=null;
function renderPieComparison(){
 const {slots,cfg,start,end}=pieComparison,result=E.compareComposition(slots.find(s=>s.month===start),slots.find(s=>s.month===end));
 const options=selected=>slots.map(s=>`<option value="${s.month}" ${s.valid?'':'disabled'} ${s.month===selected?'selected':''}>${monthLabel(s.month+'-01')}${s.valid?'':' · Veri yok'}</option>`).join('');
 $('#pieComparison').innerHTML=`<div class="pie-compare-controls"><strong>İki ayı karşılaştır</strong><label>Başlangıç<select data-pie-compare="start">${options(start)}</select></label><label>Bitiş<select data-pie-compare="end">${options(end)}</select></label></div>${result?`<p>${dateLabel(result.startDate)} → ${dateLabel(result.endDate)} · Toplam değişim ${amount(result.totalDelta)} ${unit('BS',cfg.total)} · ${E.finite(result.totalGrowth)?'%'+nf.format(result.totalGrowth):'—'}</p><div class="table-wrap"><table><thead><tr><th>Kalem</th><th>Başlangıç</th><th>Bitiş</th><th>Tutar farkı</th><th>Değişim</th><th>Paylar</th><th>Pay farkı</th></tr></thead><tbody>${result.parts.map(p=>`<tr><td>${esc(label('BS',p.row))}</td><td>${amount(p.start)}</td><td>${amount(p.end)}</td><td>${amount(p.delta)}</td><td>${change(p.growth)}</td><td>%${nf.format(p.startShare)} → %${nf.format(p.endShare)}</td><td>${change(p.shareDelta,true)}</td></tr>`).join('')}</tbody></table></div>`:'<p>Geçerli iki ay seç; bitiş ayı başlangıç ayından sonra olmalı.</p>'}`;
}
function showPieHistory(kind){
 const cfg=kind==='loans'?{title:'Kredi dağılımı',total:3,rows:[12,21,31],colors:['#245de8','#7999ef','#21a59a']}:kind==='TL'?{title:'TL mevduat dağılımı',total:38,rows:[42,50],colors:['#245de8','#7999ef']}:{title:'FX mevduat dağılımı',total:39,rows:[43,51],colors:['#21a59a','#82c9c1']};
 const latest=latestDate('BS');$('#detailTitle').textContent=cfg.title+' · Son 12 ay';$('#detailSource').textContent=names[state.group];$('#detail').classList.add('pie-history-dialog');
 const slots=E.compositionHistory(sheet('BS'),cfg.total,cfg.rows,latest||state.date);const available=slots.filter(s=>s.valid);pieComparison={slots,cfg,start:available.at(-2)?.month||'',end:available.at(-1)?.month||''};
 $('#detailBody').innerHTML=`<div class="detail-deck-action"><button class="button" data-add-pie-deck="${kind}">Dağılımı sunuma ekle →</button></div>`+'<p>Her ayın son haftalık gözlemi kullanılır. Son ay mevcut son veriyi içerir. Değişimler, önceki ayın payına göre yüzde puandır; eksik aylar karşılaştırılmaz.</p><div id="pieComparison" class="pie-comparison"></div><div class="pie-history-grid">'+slots.map(slot=>{let angle=-Math.PI/2;const svg=slot.valid?slot.parts.map((p,i)=>{const next=angle+p.share/100*2*Math.PI,mid=(angle+next)/2,start=[100+80*Math.cos(angle),100+80*Math.sin(angle)],end=[100+80*Math.cos(next),100+80*Math.sin(next)],path=p.share>=99.999?`<circle cx="100" cy="100" r="80" fill="${cfg.colors[i]}"/>`:`<path d="M100,100 L${start} A80,80 0 ${p.share>50?1:0},1 ${end} Z" fill="${cfg.colors[i]}" stroke="white" stroke-width="2"/>`;angle=next;return `<g><title>${esc(label('BS',p.row))} · ${amount(p.value)} ${unit('BS',cfg.total)} · Pay %${nf.format(p.share)}</title>`+path+`<text x="${100+53*Math.cos(mid)}" y="${100+53*Math.sin(mid)}" text-anchor="middle" dominant-baseline="middle" fill="white" font-size="12">%${nf.format(p.share)}</text></g>`;}).join(''):'';
 return `<section class="pie-month"><h3>${monthLabel(slot.month+'-01')}</h3>${slot.valid?`<svg viewBox="0 0 200 200" role="img" aria-label="${cfg.title} ${slot.month}">${svg}</svg><div class="pie-month-rows">${slot.parts.map((p,i)=>`<div><span><i style="background:${cfg.colors[i]}"></i>${esc(label('BS',p.row))}</span><strong>%${nf.format(p.share)}</strong><span>${E.finite(p.delta)?(p.delta>0?'+':'')+nf.format(p.delta)+' puan':'—'}</span></div>`).join('')}</div><p>${dateLabel(slot.date)} · Toplam ${amount(slot.total)} ${unit('BS',cfg.total)}</p>`:`<div class="empty">${slot.reason||'Aynı tarihli dağılım verisi yok.'}</div>`}</section>`;
 }).join('')+'</div>';renderPieComparison();if(!$('#detail').open)$('#detail').showModal();
}
const plRow=row=>state.basis==='cumulative'&&row>=49?row-38:row;
function overview(){
 const groupCards=(title,rows,extra='')=>`<div class="balance-group ${extra}"><div class="balance-group-heading"><h3>${title}</h3></div><div class="cards">${rows.map(row=>card('BS',row)).join('')}</div></div>`;
 const heading=(type,title,description)=>`<div class="overview-heading"><div class="overview-section-title"><span class="overview-icon" aria-hidden="true">${type==='BS'?'▤':'◴'}</span><div><h2>${title}</h2><p>${description}</p></div></div><div class="overview-section-meta"><span class="pill">${type==='BS'?'Haftalık kaynak':'Aylık kaynak'}</span><span>${type==='BS'?dateLabel(dateFor(type)):monthLabel(dateFor(type))}</span><button class="text-button" data-view="${type}">Tüm kalemler →</button></div></div>`;
 return `<div class="panel overview-highlights"><div class="panel-head"><h3>Öne çıkan hareketler</h3><span class="pill">${dataset.demo?'ÖRNEK SENARYO':'MoM'}</span></div><div class="highlights-grid">${insights()}</div></div><div class="overview-entry"><div class="panel loan-pie-panel"><div class="panel-head"><h3>Toplam kredilerin dağılımı</h3><span class="pill">${names[state.group]}</span></div>${loanPie()}</div><div class="panel loan-pie-panel deposit-pie-panel"><div class="panel-head"><h3>Mevduat dağılımı</h3><span class="pill">${names[state.group]}</span></div><div class="deposit-pies"><section aria-label="TL mevduat dağılımı"><h4>TL mevduat</h4>${loanPie('TL')}</section><section aria-label="FX mevduat dağılımı"><h4>FX mevduat</h4>${loanPie('FX')}</section></div></div></div><div class="overview-sections"><section class="overview-block" aria-label="Bilanço">${heading('BS','Bilanço','Kredi büyümesi, mevduat ve fonlama dengesi')}${groupCards('Krediler',[3,4,6,12,21,31,28,57])}${groupCards('Mevduat',[37,38,39,41,49],'deposit-group')}</section><section class="overview-block" aria-label="P&L">${heading('PL','P&L','Gelirler, maliyetler ve kârlılık')}<div class="cards">${[65,49,53,57,61,70,68,69].map(row=>card('PL',plRow(row))).join('')}</div></section></div>`;
}
function insights(){
 const result=InsightHighlights.analyze(dataset,T,state.group),themes={growth:'Büyüme',funding:'Fonlama',risk:'NPL'};
 if(!result.cards.length)return '<div class="empty">Bilanço gelişmeleri için aynı tarihli, geçerli güncel ve baz veriler gerekiyor.</div>';
 const num=v=>nf.format(Math.abs(v)),signed=v=>(v>0?'+':'')+nf.format(v);
 return result.cards.map((x,i)=>{const first=label('BS',x.rows[0]),second=x.rows[1]?label('BS',x.rows[1]):'',direction=x.value>0?'yükseldi':'geriledi';let title='',text='';
 if(x.kind==='growth'){title=first+' '+(x.value>0?'arttı':'azaldı')+': %'+num(x.value);text='Mutlak fark '+signed(x.delta/state.unit)+' '+unit('BS',x.row)+'.';}
 else if(x.kind==='ratio'){title=first+' '+direction+': '+signed(x.value)+' puan';text='Oran %'+nf.format(x.previous)+' → %'+nf.format(x.current)+'.';}
 else if(x.kind==='share'){title=(x.id==='shareTL'?'TL':'FX')+' vadesiz mevduat payı '+direction; text='Pay %'+nf.format(x.previous)+' → %'+nf.format(x.current)+'; '+signed(x.value)+' puan.';}
 else if(x.kind==='product'){title=first+' büyümesi toplam kredilerden '+num(x.value)+' puan '+(x.value>0?'yüksek':'düşük');text='Ürün MoM %'+nf.format(x.left)+'; toplam kredi MoM %'+nf.format(x.right)+'.';}
 else if(x.kind==='currency'){title=(x.id==='creditFX'?'Kredilerde':'Mevduatta')+' TL / FX büyüme farkı: '+signed(x.value)+' puan';text='TL MoM %'+nf.format(x.left)+'; USD MoM %'+nf.format(x.right)+'. Para birimleri kendi içinde karşılaştırılır.';}
 else if(x.kind==='fundingGap'){title='Kredi / mevduat büyüme farkı: '+signed(x.value)+' puan';text='Kredi MoM %'+nf.format(x.left)+'; mevduat MoM %'+nf.format(x.right)+'.';}
 else if(x.kind==='groups'){title=first+': özel / kamu büyüme farkı '+signed(x.value)+' puan';text='Özel MoM %'+nf.format(x.left)+'; kamu MoM %'+nf.format(x.right)+'.';}
 else {title='Kredi büyümesi '+(x.value>0?'hızlandı':'yavaşladı')+': '+num(x.value)+' puan';text='MoM %'+nf.format(x.right)+' → %'+nf.format(x.left)+'.';}
 return `<div class="insight"><span class="number">0${i+1}</span><div><span class="source-text">${themes[x.theme]}${x.provisional?' · Geçici dönem':''}</span><strong>${esc(title)}</strong><p>${esc(text)} ${dateLabel(x.baseDate)} → ${dateLabel(x.date)}.</p><button class="text-button" data-metric="BS:${x.rows[0]}">Kalemi incele</button><details class="highlight-method"><summary>Hesaplama</summary><p>${x.percentile!==null?'Son 12 tamamlanmış dönem üzerinden kendi geçmişindeki medyandan sapma sıralaması kullanıldı.':x.provisional?'Geçici dönem geçmiş olağandışılık sıralamasına alınmadı; temanın öncelik sırası kullanıldı.':'Yeterli geçmiş olmadığı için temanın öncelik sırası kullanıldı.'} Bu kart finansal önem veya iyi/kötü performans puanı değildir.</p></details></div></div>`;
 }).join('');
}
function comparison(){return `<div class="panel"><div class="panel-head"><h3>Banka grupları yan yana</h3><span class="muted">Aynı analiz tarihi · mevcut kaynak dönemleri</span></div><div class="table-wrap"><table><thead><tr><th>Kalem</th>${['Sektör','Ozel','Kamu'].map(g=>`<th>${names[g]}</th><th>${g==='Sektör'?'YoY':'MoM'}</th>`).join('')}</tr></thead><tbody>${[['BS',3],['BS',37],['BS',57],['PL',65],['PL',49],['PL',70]].map(([type,id])=>{const row=type==='PL'?plRow(id):id;return `<tr><td>${esc(label(type,row))}<div class="source-text">${type==='BS'?'Haftalık stok':'Aylık'} · ${ratio(type,row)?'%':unit(type,row)}</div></td>${['Sektör','Ozel','Kamu'].map(g=>{const m=metric(type,row,g);return `<td>${amount(m.current?.value,ratio(type,row))}<div class="source-text">${dateLabel(m.current?.date)}</div></td><td>${change(g==='Sektör'?m.yoyChange:m.change,ratio(type,row))}</td>`}).join('')}</tr>`;}).join('')}</tbody></table></div><div class="details-note">Sektör toplamı kaynak sheetten alınır. Özel + kamu toplamının sektörü kapsadığı varsayılmaz. Kaynak tarihleri hücrelerde görünür; farklı dönemli rakamlar doğrudan pazar payına çevrilmez.</div></div>`;}
function dataPage(){return `<div class="panel"><div class="panel-head"><h3>Veri kaynakları</h3><span class="pill">dataa.xlsx</span></div><div class="source-grid">${['BS','PL'].flatMap(type=>['Sektör','Ozel','Kamu'].map(g=>{const s=sheet(type,g),count=s?.rows.reduce((n,r)=>n+r.values.filter(E.finite).length,0)||0;return `<div class="source-item"><strong>${type==='BS'?'BS':'P&L'}_${g}</strong><span class="muted">${s?'Sheet mevcut':'Sheet yok'} · ${count} sayısal hücre</span><br>${type==='BS'?'Haftalık · 1. satır tarihler':'Aylık · 2. satır tarihler'}<br>${s?dateLabel(s.dates[0])+' – '+dateLabel(s.dates.at(-1)):''}</div>`;})).join('')}</div><div class="method"><h3>Karşılaştırma kuralları</h3><ul><li>BS, dönem sonu stoktur. MoM hedefi mevcut gözlemin bir takvim ayı önceki tarihidir; ayda aynı gün yoksa ayın son günü kullanılır. Haftalık kaynakta hedef tarihte veya en fazla 7 gün öncesinde bulunan son geçerli gözlem baz alınır. Sonraki tarih kullanılmaz; uygun baz yoksa değişim “—” gösterilir. YoY önceki yılın aynı tarihinden en fazla 7 gün önceki gözlemdir. YTD önceki yılın 31 Aralık tarihinden en fazla 7 gün önceki gözleme göre hesaplanır.</li><li>P&L aylık görünüm, şablondaki Monthly satırlarını kullanır. MoM önceki takvim ayını, YoY önceki yılın aynı ayını karşılaştırır. Kümülatif görünüm Cumulative satırlarını korur. YTD tutarı, kümülatif kaynak satırından alınır; aylık tutar ile karşılaştırılmaz. Kartlarda YTD seçildiğinde P&L, önceki yılın aynı ayındaki kümülatif değere göre YTD YoY değişimini gösterir.</li><li>TL değişimi: <code>(mevcut / baz − 1) × 100</code>. Oran değişimleri yüzde puan olarak gösterilir. Baz sıfır veya negatifse büyüme yüzdesi hesaplanmaz; detayda tutar farkı incelenebilir.</li><li>Son geçerli BS gözlemi en fazla 7 gün, P&L gözlemi en fazla 32 gün geri olabilir. Kalem tarihleri ayrıca gösterilir. Daha eski veri güncelmiş gibi kullanılmaz.</li><li>Boş hücre sıfır değildir. Excel hata hücreleri ve hesaplanmış değer önbelleği bulunmayan formüller kullanılamaz. Excel’i hesaplayıp kaydedin, ardından Veriyi yenile düğmesine basın.</li><li>Format sütununa göre TL tutarlar milyon TL, USD tutarlar milyon USD ve % kalemler orandır. USD değerler TL’ye çevrilmez veya TL kalemlerle toplanmaz. Görüntüleme birimi yalnızca ekrandaki tutarları değiştirir: milyon TL için kaynak değer, milyar TL için kaynak değer / 1.000, trilyon TL için kaynak değer / 1.000.000 kullanılır. Yüzdeler ve yüzde puan değişimleri bu seçimden etkilenmez. Oranlarda Excel yüzde biçimi kullanılıyorsa 0,036 değeri %3,6 gösterilir; yüzde biçimi yoksa kaynak değer yüzde puan kabul edilir.</li><li>Kredi / mevduat oranı kaynakta boşsa aynı tarihteki (Gross) Krediler / Mevduatlar ile hesaplanır; kaynağı detayda belirtilir. Nominal TL hareketlerinden reel büyüme veya kur etkisinden arındırılmış büyüme sonucu çıkarılmaz.</li></ul><h3>Dönem güncellemeleri</h3><p>BS haftalık, P&L aylık olarak bağımsız güncellenir. Yeni dönem sütunları otomatik okunur; boş gelecek dönemler seçilmez. Her yenilemede BS ve P&L kendi son açıklanan dolu dönemlerini gösterir. Önceki dönem sütunlarını saklayın: MoM, YoY ve YTD karşılaştırmaları dosyadaki geçmiş gözlemlere dayanır. Yeni hafta geldiğinde henüz yayımlanmayan aya ait P&L üretilmez; her kalemin kaynak tarihi gösterilir. Excel hesaplanıp kaydedildikten sonra yeni değerler okunabilir.</p><h3>Otomatik okuma kontrolü</h3><p>Satır başlıkları ve tarih satırları şablonla doğrulanır. Eşleşmeyen satırlar atlanır; başka bir kalem gibi yorumlanmaz. Aynı kalem isminin tekrarlandığı P&L bölümleri satır konumları ile ayrılır.</p>${dataset.warnings.length?`<div class="error">${dataset.warnings.slice(0,30).map(esc).join('<br>')}${dataset.warnings.length>30?'<br>Diğer uyarılar: '+(dataset.warnings.length-30):''}</div>`:'<p>Dosya okuma uyarısı yok.</p>'}<h3>Öne çıkan gelişmeler nasıl seçilir?</h3><p>Yalnızca bilanço kalemleri; büyüme, fonlama ve NPL temalarında aynı tarihli verilerle değerlendirilir. Yeterli tamamlanmış geçmişte kendi medyanına göre sapma sıralaması; geçici dönemde tema öncelikleri kullanılır. Bu sıralama finansal önem veya olumlu / olumsuz performans değerlendirmesi değildir. Detaylarda büyüklük, baz etkisi ve alt kalemler birlikte incelenir.</p><h3>Gizlilik ve sonraki faz</h3><p>Aynı klasördeki dataa.xlsx, yalnızca bilgisayarındaki yerel sunucudan okunur. Dış servise gönderilmez, sunucuda veya tarayıcı depolamasında kaydedilmez. Gerçek veri senin sekmende kalır. Sunum editörü düzenlenebilir PowerPoint ve PDF çıktısı sağlar.</p></div></div>`;}
function render(){
 let basisControl=document.querySelector('#plBasis');if(!basisControl){basisControl=document.createElement('div');basisControl.id='plBasis';basisControl.className='segmented';basisControl.setAttribute('aria-label','P&L ölçüm dönemi');document.querySelector('.toolbar').append(basisControl);}basisControl.hidden=!['overview','PL','compare'].includes(state.view);basisControl.innerHTML=`<button data-basis="monthly" class="${state.basis==='monthly'?'selected':''}">P&L · Aylık</button><button data-basis="cumulative" class="${state.basis==='cumulative'?'selected':''}">P&L · Kümülatif</button>`;

 $('#refreshData').disabled=loadState==='loading';
 document.querySelector('.toolbar').hidden=['deck','data'].includes(state.view);
 const titles={deck:['Sunumunu oluştur.','Kalemleri ve dönemleri seç, düzenlenebilir PowerPoint olarak indir.','Sunum oluştur'],overview:['Sektöre geniş açıdan bak.','Büyüme, fonlama ve kârlılık; aynı çalışma alanında.','Genel bakış'],BS:['Bilanço, detaylarıyla.','Haftalık kaynak verilerle aylık stok değişimi ve finansal kalemlerin kırılımı.','Bilanço'],PL:['Kârlılığın kaynaklarını gör.','Aylık akımlar ve yılbaşından itibaren birikimli sonuçlar.','Kârlılık'],compare:['Aynı sektör, farklı dinamikler.','Sektör, özel ve kamu bankalarının karşılaştırmalı görünümü.','Grup karşılaştırması'],data:['Analizin dayanağı.','Kaynak yapısı, dönem kuralları ve veri kontrolleri.','Veri & yöntem']},t=titles[state.view];$('#title').textContent=t[2];$('#subtitle').textContent=t[1];$('#crumb').textContent=t[2];
 document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===state.view));document.querySelectorAll('[data-group]').forEach(b=>b.classList.toggle('selected',b.dataset.group===state.group));
 $('#mode').textContent=loadState==='loading'?'VERİ OKUNUYOR':loadState==='error'?'VERİ YOK':dataset.demo?'DEMO VERİ':'YEREL EXCEL';$('#notice').classList.toggle('error',loadState==='error');$('#notice').textContent=loadState==='loading'?'dataa.xlsx okunuyor…':loadState==='error'?loadError:dataset.hasValues===false?'dataa.xlsx okundu; sayısal veri bulunmuyor. Boş hücreler “—” gösterilir.':`dataa.xlsx · BS: ${dateLabel(dateFor('BS'))} · P&L: ${monthLabel(dateFor('PL'))} · Son açıklanan dönemler · Son okuma: ${lastRead?lastRead.toLocaleTimeString('tr-TR'):'—'}. Excel’i kaydedip Veriyi yenile’ye basın.`;
 let body='';if(state.view==='overview')body=overview();else if(state.view==='compare')body=comparison();else if(state.view==='data')body=dataPage();else if(state.view==='deck')body=InsightDeck.render({dataset,template:T,label,loadState});else if(state.view==='BS')body=section('Temel bilanço kalemleri','BS',[3,31,37,57])+`<div class="panel" style="margin-top:24px"><div class="panel-head"><h3>Bilanço kalemleri</h3><span class="muted">${names[state.group]}</span></div>${table('BS',T.BS.rows.map(r=>r.row))}</div>`;else{
 const cu=state.basis==='cumulative',rows=cu?[27,11,15,32]:[65,49,53,70];body=section(cu?'Birikimli sonuçlar':'Aylık sonuçlar','PL',rows)+`<div class="panel" style="margin-top:24px"><div class="details-note">${cu?'Kümülatif tutarlar yıl başından seçili aya kadardır. MoM, birikimli seviyelerin değişimidir; aylık kâr artışı olarak yorumlanmaz. YoY aynı ayın önceki yıl birikimli tutarıdır.':'Monthly satırları kullanılır. YTD tutarları Cumulative bölümünden gelir.'}</div>${table('PL',T.PL.rows.filter(r=>cu?r.row>=11&&r.row<=45:r.row>=49).map(r=>r.row))}</div>`;
 }
 const control=['overview','BS','PL'].includes(state.view)?`<div class="section-head" style="margin:0 0 18px"><span class="muted">${names[state.group]} · ${(state.unit===1000000?'Trilyon':state.unit===1000?'Milyar':'Milyon')} · TL / USD</span><div class="mini-controls" aria-label="Kart karşılaştırması"><button data-horizon="change" class="${state.horizon==='change'?'selected':''}">MoM</button><button data-horizon="yoyChange" class="${state.horizon==='yoyChange'?'selected':''}">YoY</button><button data-horizon="ytdChange" class="${state.horizon==='ytdChange'?'selected':''}">YTD</button></div></div>`:'';
 let changes=document.querySelector('#changeBasis');if(!changes){changes=document.createElement('div');changes.id='changeBasis';document.querySelector('.toolbar').append(changes);}changes.hidden=!control;changes.innerHTML=control?control.slice(control.indexOf('<div class="mini-controls"'),control.lastIndexOf('</div>')):'';
 const notice=$('#notice');notice.title=notice.textContent;if(loadState==='ready')notice.textContent=`BS · ${dateLabel(dateFor('BS'))}    |    P&L · ${monthLabel(dateFor('PL'))}`;
 $('#screen').innerHTML=body;
}
function showDetail(type,row){$('#detail').classList.remove('pie-history-dialog');const m=metric(type,row),r=ratio(type,row),s=getSeries(type,row),source=sheet(type);$('#detailTitle').textContent=label(type,row);$('#detailSource').textContent=names[state.group]+' · '+(type==='BS'?'HAFTALIK BİLANÇO':row<49?'KÜMÜLATİF P&L':'AYLIK P&L');
 const childRowsAll=type==='BS'?(children[row]||[]):({65:[49,53,54,55,57,61,62,64],49:[50,51],57:[58,59]})[row]||[];
 const childRows=childRowsAll.filter(id=>T[type].rows.some(r=>r.row===id));
 const cu=type==='PL'&&cumulative[row]?E.cumulativeYoY(source,cumulative[row],latestDate(type)||state.date,r):type==='PL'&&row>=11&&row<=45?{current:m.current,change:m.yoyChange}:null;
 $('#detailBody').innerHTML=`<div class="detail-deck-action"><button class="button" data-add-to-deck="${type}:${row}">Sunuma ekle →</button></div><div class="stat-strip"><div><span>Mevcut değer · ${dateLabel(m.current?.date)}</span><strong>${amount(m.current?.value,r)} ${r?'':unit(type,row)}</strong></div><div><span>${type==='BS'?'MoM':'MoM'} · ${dateLabel(m.prior?.date)}</span><strong>${change(m.change,r)}</strong></div><div><span>YoY · ${dateLabel(m.yoy?.date)}</span><strong>${change(m.yoyChange,r)}</strong></div><div><span>${type==='BS'?'YTD · '+dateLabel(m.ytd?.date):'YTD birikimli tutar'}</span><strong>${type==='BS'?change(m.ytdChange,r):cu?amount(cu.current?.value,r)+(r?'':' '+unit(type,row)):'—'}</strong></div></div>${chartControls(type,row)}${chart(chartPoints(type,row,detailMode(type,row)),{isRatio:r,level:detailMode(type,row)==='nominal',title:detailMode(type,row)==='nominal'?'Oran':horizonLabel(type)})}<div class="details-note">Kaynak: ${esc(source?.name||'Sheet yok')} · A${T[type].rows.find(r=>r.row===row)?.sourceRow??row} · ${esc(displayLabel(type,T[type].rows.find(r=>r.row===row)?.label))}<br>${m.current?'Kullanılan mevcut tarih: '+dateLabel(m.current.date)+'. '+esc(displayLabel(type,m.current.source)):'Bu kalem için seçili tarih aralığında geçerli veri yok.'}<br>${m.prior&&m.current?'Mutlak dönem farkı: '+amount(m.current.value-m.prior.value,r)+(r?' puan':' '+unit(type,row))+'. ':''}${cu?'YTD YoY: '+(E.finite(cu.change)?(r?nf.format(cu.change)+' puan':'%'+nf.format(cu.change)):'karşılaştırma verisi yok')+'. ':''}Eksik veya sıfır / negatif baz nedeniyle yüzdesi hesaplanamayan değişimler “—” gösterilir.</div>${childRows.length?`<div class="section-head"><h3>İlgili alt kalemler</h3></div>${table(type,childRows)}<p class="muted">Alt kalemler arasında iç içe kırılımlar olabilir; satırlar otomatik olarak toplanmaz.</p>`:''}<div class="section-head"><h3>Dönem geçmişi</h3></div><div class="table-wrap"><table><thead><tr><th>Tarih</th><th>${r?'%':unit(type,row)}</th></tr></thead><tbody>${s.filter(p=>p.date<=state.date).slice(-12).reverse().map(p=>`<tr><td>${dateLabel(p.date)}</td><td>${amount(p.value,r)}</td></tr>`).join('')}</tbody></table></div>`;if(!$('#detail').open)$('#detail').showModal();}
document.addEventListener('click',e=>{
if(e.target.closest('[data-deck-action],[data-deck-slide],[data-deck-widget],[data-deck-panel],[data-deck-remove-row]')){InsightDeck.click(e,render);return;}
const b=e.target.closest('button,[data-metric]');if(!b)return;
if(b.dataset.addToDeck){const [type,id]=b.dataset.addToDeck.split(':');InsightDeck.addFromMetric({dataset,template:T,label,loadState},{type,row:Number(id),group:state.group,unit:state.unit,mode:detailMode(type,Number(id)),end:latestDate(type)?.slice(0,7),months:12});$('#detail').close();state.view='deck';render();return;}
if(b.dataset.addPieDeck){const kind=b.dataset.addPieDeck,rows=kind==='loans'?[12,21,31]:kind==='TL'?[42,50]:[43,51];InsightDeck.addFromMetric({dataset,template:T,label,loadState},{type:'BS',row:rows[0],rows,kind:'pie',title:kind==='loans'?'Kredi dağılımı':kind+' mevduat dağılımı',mode:'nominal',group:state.group,unit:state.unit,end:latestDate('BS')?.slice(0,7),months:12});$('#detail').close();state.view='deck';render();return;}
if(b.dataset.pieHistory){showPieHistory(b.dataset.pieHistory);return;}
if(b.dataset.detailHorizon){if(b.dataset.detailHorizon==='nominal')detailLevelKey=b.dataset.detailKey;else{detailLevelKey='';state.horizon=b.dataset.detailHorizon;}render();const [type,row]=b.dataset.detailKey.split(':');showDetail(type,Number(row));}
if(b.dataset.view){state.view=b.dataset.view;render();}if(b.dataset.group){state.group=b.dataset.group;render();}if(b.dataset.horizon){state.horizon=b.dataset.horizon;render();}if(b.dataset.basis){state.basis=b.dataset.basis;render();}
if(b.dataset.metric){const [type,row]=b.dataset.metric.split(':');showDetail(type,Number(row));}
if(b.id==='refreshData')loadWorkbook();
if(b.id==='closeDetail')$('#detail').close();
});
document.addEventListener('keydown',e=>{if(e.target.matches('tr[data-metric]')&&['Enter',' '].includes(e.key)){e.preventDefault();e.target.click();}});
$('#unit').addEventListener('change',e=>{state.unit=Number(e.target.value);render();});document.addEventListener('change',e=>{if(e.target.dataset.pieCompare&&pieComparison){pieComparison[e.target.dataset.pieCompare]=e.target.value;renderPieComparison();return;}if(e.target.id==='trendSelect'){state.trend=Number(e.target.value);render();}});

async function loadWorkbook(){
 const token=++loadToken;
 loadState='loading';loadError='';dataset={sheets:[],warnings:[],demo:false};render();
 try{
  if(!['http:','https:'].includes(location.protocol))throw Error('Aynı klasördeki Excel’i otomatik okumak için Baslat.bat (Windows) veya Baslat.command (Mac) ile açın.');
  const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),20000);
  let response;
  try{response=await fetch('./dataa.xlsx',{cache:'no-store',signal:controller.signal});}finally{clearTimeout(timer);}
  if(!response.ok)throw Error(response.status===404?'dataa.xlsx bulunamadı. Veri Excel’ini index.html ile aynı klasöre dataa.xlsx adıyla koyup sayfayı yenileyin.':'dataa.xlsx okunamadı (HTTP '+response.status+').');
  const size=Number(response.headers.get('Content-Length'));
  if(size>20*1024*1024)throw Error('dataa.xlsx 20 MB sınırını aşıyor.');
  const file=await response.blob();
  const loaded=await LocalXLSX.read(file,T);
  if(token!==loadToken)return;
  dataset={...loaded,demo:loaded.demo===true,hasValues:loaded.sheets.some(s=>s.rows.some(r=>r.values.some(E.finite)))};loadState='ready';
  // Ignore empty future headers; start at the latest populated observation.
  const dates=loaded.sheets.flatMap(s=>s.dates.filter((d,i)=>s.rows.some(r=>E.finite(r.values[i]))));
  const latest=dates.sort().at(-1);
  if(latest)state.date=latest;
  lastRead=new Date();render();
  const count=loaded.sheets.reduce((n,s)=>n+s.rows.reduce((n,r)=>n+r.values.filter(E.finite).length,0),0);
  if(!count)$('#notice').textContent='dataa.xlsx okundu; sayısal veri bulunmuyor. Boş hücreler “—” gösterilir.';
 }catch(error){
  if(token!==loadToken)return;
  loadState='error';loadError=error.name==='AbortError'?'dataa.xlsx okuma süresi doldu. Dosyayı kontrol edip sayfayı yenileyin.':error.message;render();
 }
}
const today=new Date();state.date=[today.getFullYear(),String(today.getMonth()+1).padStart(2,'0'),String(today.getDate()).padStart(2,'0')].join('-');
loadWorkbook();

if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'set_insightbase_view',description:'InsightBase görünümünü ve banka grubunu değiştirir. Excel verisi okumaz veya dışarı aktarmaz.',inputSchema:{type:'object',properties:{view:{type:'string',enum:['overview','BS','PL','compare','deck','data']},group:{type:'string',enum:['Sektör','Ozel','Kamu']}},required:['view'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!input||!['overview','BS','PL','compare','deck','data'].includes(input.view)||input.group&&!['Sektör','Ozel','Kamu'].includes(input.group))throw Error('Geçersiz görünüm / grup.');state.view=input.view;if(input.group)state.group=input.group;render();return {view:state.view,group:state.group,mode:dataset.demo?'demo':'local'};}})).catch(()=>{});}catch{}}

document.addEventListener('change',e=>{if(state.view==='deck')InsightDeck.change(e,render);});

for(const event of ['dragstart','dragover','drop','dragend'])document.addEventListener(event,e=>{if(state.view==='deck')InsightDeck.drag(e,render);});

document.addEventListener('input',e=>{if(state.view==='deck'&&e.target.dataset.deckSearch)InsightDeck.search(e,render);});
